-- NCR Process on the existing workflow builder, plus SLA columns on each NCR.
-- The six-step NCR status column is not changed.
ALTER TABLE "ncr" ADD COLUMN IF NOT EXISTS "workflow_stage" text;--> statement-breakpoint
ALTER TABLE "ncr" ADD COLUMN IF NOT EXISTS "process_data" jsonb;--> statement-breakpoint
ALTER TABLE "ncr" ADD COLUMN IF NOT EXISTS "sla_target_date" timestamp;--> statement-breakpoint
ALTER TABLE "ncr" ADD COLUMN IF NOT EXISTS "sla_due_date" timestamp;--> statement-breakpoint
ALTER TABLE "ncr" ADD COLUMN IF NOT EXISTS "sla_status" text;--> statement-breakpoint
ALTER TABLE "ncr" ADD COLUMN IF NOT EXISTS "sla_warning_sent" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "ncr" ADD COLUMN IF NOT EXISTS "sla_escalated" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "ncr" ADD COLUMN IF NOT EXISTS "stage_due_date" timestamp;--> statement-breakpoint
ALTER TABLE "ncr" ADD COLUMN IF NOT EXISTS "days_open" integer;--> statement-breakpoint
ALTER TABLE "ncr" ADD COLUMN IF NOT EXISTS "days_in_stage" integer;--> statement-breakpoint
INSERT INTO "workflow_definitions" ("name", "module", "is_active", "definition", "version", "version_history")
SELECT 'NCR Process', 'ncr', 'false', $ncrdef${"nodes":[{"id":"t1","type":"trigger","kind":"submitted","label":"NCR Submitted","position":{"x":40,"y":80},"config":{"startEvent":"User submits the NCR form","mappedFields":["ncr_number","reported_by","date_opened","department","part_number","job_number","lot_number","supplier","customer","description","severity","ncr_type"],"outputs":{"status":"Submitted","workflow_stage":"Quality Review"}}},{"id":"a2","type":"action","kind":"ncr_process","label":"Initialize NCR","position":{"x":320,"y":80},"config":{"process":"ncr","workflowStage":"Quality Review","updates":{"status":"Submitted","workflow_stage":"Quality Review","date_opened":"current date"},"assignments":["quality_manager","department_manager"],"notify":["Quality Manager","Department Manager"]}},{"id":"p_side","type":"parallel","kind":"parallel","label":"Side paths","position":{"x":320,"y":520},"config":{"process":"ncr","note":"Open more than 30 days, customer NCR, and supplier NCR. These do not replace the main path."}},{"id":"c_open","type":"condition","kind":"days_open","label":"Open more than 30 days","position":{"x":600,"y":420},"config":{"field":"days_open","greaterThan":30}},{"id":"a_open","type":"action","kind":"ncr_process","label":"Escalate open NCR","position":{"x":900,"y":420},"config":{"process":"ncr","notify":["Quality Manager","Operations Manager","Executive Sponsor"],"updates":{"escalation_level":"High"},"note":"Return to the current step. The stage does not change."}},{"id":"c_cust","type":"condition","kind":"ncr_type","label":"Customer NCR","position":{"x":600,"y":620},"config":{"field":"ncr_type","in":["Customer","customer"]}},{"id":"a_cust","type":"action","kind":"ncr_process","label":"Customer response","position":{"x":900,"y":620},"config":{"process":"ncr","notify":["Sales Manager","Quality Manager"],"fields":["customer_response_due"],"updates":{"customer_response_due_hours":48}}},{"id":"c_sup","type":"condition","kind":"ncr_type","label":"Supplier NCR","position":{"x":600,"y":820},"config":{"field":"ncr_type","in":["Supplier","supplier"]}},{"id":"a_sup","type":"action","kind":"ncr_process","label":"Create SCAR","position":{"x":900,"y":820},"config":{"process":"ncr","assignments":["Supplier Quality Engineer"],"notify":["Supplier Quality Engineer","Quality Manager"],"fields":["supplier_response","supplier_corrective_actions"],"note":"Quality record on scar_forms. The SCAR number stays blank until someone assigns one."}},{"id":"c_crit","type":"condition","kind":"severity","label":"Critical NCR","position":{"x":640,"y":80},"config":{"field":"severity","in":["Critical","critical"]}},{"id":"a_crit","type":"action","kind":"ncr_process","label":"Notify executives","position":{"x":640,"y":300},"config":{"process":"ncr","notify":["President","CEO","Operations Director"],"updates":{"priority":"Critical"},"note":"These titles are notification targets stored on this step."}},{"id":"ap_exec","type":"approval","kind":"approval","label":"Executive Approval","position":{"x":940,"y":300},"config":{"process":"ncr","assignees":["President","CEO","Operations Director"],"approvalMode":"any","message":"A Critical NCR needs executive approval before Quality Review."}},{"id":"ap3","type":"approval","kind":"approval","label":"Quality Review","position":{"x":1100,"y":80},"config":{"process":"ncr","workflowStage":"Quality Review","assignees":["Quality Manager"],"approvalMode":"all","requiredFields":["severity","disposition","review_notes","containment_required"],"buttons":["Approve","Reject"],"message":"Review severity, disposition, notes, and whether containment is required."}},{"id":"c4","type":"condition","kind":"containment","label":"Containment Required?","position":{"x":1400,"y":80},"config":{"anyOf":[{"field":"severity","in":["Major","Critical","major","critical","high","medium"]},{"field":"containment_required","in":["Yes","yes",true]}]}},{"id":"a5","type":"action","kind":"ncr_process","label":"Reject NCR","position":{"x":1100,"y":360},"config":{"process":"ncr","workflowStage":"Rejected","updates":{"status":"Rejected","workflow_stage":"Rejected","rejected_date":"current date","rejected_by":"current user","rejection_reason":"approval comments"}}},{"id":"e6","type":"end","kind":"end","label":"NCR Rejected","position":{"x":1400,"y":360},"config":{}},{"id":"a7","type":"action","kind":"ncr_process","label":"Containment Activities","position":{"x":1400,"y":280},"config":{"process":"ncr","workflowStage":"Containment","fields":["containment_required","containment_owner","containment_action","containment_date","inventory_hold","shipment_hold"],"updates":{"status":"Containment"},"note":"inventory_hold and shipment_hold are yes/no fields on this NCR."}},{"id":"a8","type":"action","kind":"ncr_process","label":"Root Cause Analysis","position":{"x":1720,"y":80},"config":{"process":"ncr","workflowStage":"Root Cause Analysis","requiredFields":["root_cause_method","root_cause","escape_point","contributing_factors"],"rootCauseMethods":["5 Why","Fishbone","8D","FTA"],"updates":{"status":"Root Cause Analysis"}}},{"id":"a9","type":"action","kind":"ncr_process","label":"Corrective Action Planning","position":{"x":2020,"y":80},"config":{"process":"ncr","workflowStage":"Corrective Action","fields":["corrective_action","action_owner","due_date"],"updates":{"status":"Corrective Action"}}},{"id":"c_od","type":"condition","kind":"corrective_action_overdue","label":"Corrective action overdue?","position":{"x":2320,"y":80},"config":{"field":"corrective_action_overdue","equals":"Yes"}},{"id":"a_od","type":"action","kind":"ncr_process","label":"Raise overdue corrective action","position":{"x":2320,"y":300},"config":{"process":"ncr","notify":["action owner","Quality Manager"],"updates":{"priority":"raised","dashboard_alert":"Corrective action is overdue"}}},{"id":"p10","type":"parallel","kind":"parallel","label":"Implement Corrective Actions","position":{"x":2620,"y":80},"config":{"process":"ncr","workflowStage":"Implementation","note":"Wait for procedure, training, and inspection updates."}},{"id":"a11","type":"action","kind":"ncr_process","label":"Update Procedure","position":{"x":2920,"y":0},"config":{"process":"ncr","workflowStage":"Implementation","fields":["procedure_update_required","procedure_update_owner","procedure_update_due_date","procedure_update_complete","procedure_evidence"],"doneWhen":{"procedure_update_complete":"Yes"}}},{"id":"a12","type":"action","kind":"ncr_process","label":"Operator Training","position":{"x":2920,"y":180},"config":{"process":"ncr","workflowStage":"Implementation","fields":["training_required","training_owner","training_due_date","training_complete","training_evidence"],"doneWhen":{"training_complete":"Yes"}}},{"id":"a13","type":"action","kind":"ncr_process","label":"Inspection Plan Update","position":{"x":2920,"y":360},"config":{"process":"ncr","workflowStage":"Implementation","fields":["inspection_update_required","inspection_owner","inspection_due_date","inspection_update_complete","inspection_evidence"],"doneWhen":{"inspection_update_complete":"Yes"}}},{"id":"ap14","type":"approval","kind":"approval","label":"Management Approval","position":{"x":3240,"y":80},"config":{"process":"ncr","workflowStage":"Management Approval","assignees":["Quality Manager","Operations Manager"],"approvalMode":"all","requiredFields":["approval_comments","approved_by","approval_date"],"buttons":["Approve","Return For Changes"],"message":"Quality Manager and Operations Manager both approve, or return the plan for changes."}},{"id":"a15","type":"action","kind":"ncr_process","label":"Effectiveness Verification","position":{"x":3540,"y":80},"config":{"process":"ncr","workflowStage":"Effectiveness Verification","fields":["effective","verification_notes","verified_by","verification_date","recurrence_detected"],"updates":{"status":"Effectiveness Verification"}}},{"id":"c16","type":"condition","kind":"effective","label":"Effective?","position":{"x":3840,"y":80},"config":{"allOf":[{"field":"effective","in":["Yes","yes",true]},{"field":"recurrence_detected","in":["No","no",false]}]}},{"id":"a17","type":"action","kind":"ncr_process","label":"Close NCR","position":{"x":4140,"y":80},"config":{"process":"ncr","workflowStage":"Closed","updates":{"status":"Closed","workflow_stage":"Closed","date_closed":"current date","days_open":"date_closed minus date_opened","closure_notes":"verification notes"},"note":"Generate the NCR PDF from the existing NCR layout, archive the record, and lock it."}},{"id":"e18","type":"end","kind":"end","label":"NCR Closed","position":{"x":4440,"y":80},"config":{}}],"edges":[{"from":"t1","to":"a2"},{"from":"a2","to":"p_side"},{"from":"a2","to":"c_crit"},{"from":"p_side","to":"c_open"},{"from":"p_side","to":"c_cust"},{"from":"p_side","to":"c_sup"},{"from":"c_open","to":"a_open","branch":"true","label":"Yes"},{"from":"a_open","to":"c_open","label":"Return to current step"},{"from":"c_cust","to":"a_cust","branch":"true","label":"Yes"},{"from":"c_sup","to":"a_sup","branch":"true","label":"Yes"},{"from":"c_crit","to":"a_crit","branch":"true","label":"Yes"},{"from":"a_crit","to":"ap_exec"},{"from":"ap_exec","to":"ap3","branch":"approved","label":"Continue"},{"from":"c_crit","to":"ap3","branch":"false","label":"No"},{"from":"ap3","to":"c4","branch":"approved","label":"Approve"},{"from":"ap3","to":"a5","branch":"rejected","label":"Reject"},{"from":"a5","to":"e6"},{"from":"c4","to":"a7","branch":"true","label":"Yes"},{"from":"c4","to":"a8","branch":"false","label":"No"},{"from":"a7","to":"a8"},{"from":"a8","to":"a9"},{"from":"a9","to":"c_od"},{"from":"c_od","to":"p10","branch":"false","label":"No"},{"from":"c_od","to":"a_od","branch":"true","label":"Yes"},{"from":"a_od","to":"a9","label":"Return to the task"},{"from":"p10","to":"a11"},{"from":"p10","to":"a12"},{"from":"p10","to":"a13"},{"from":"a11","to":"ap14"},{"from":"a12","to":"ap14"},{"from":"a13","to":"ap14"},{"from":"ap14","to":"a15","branch":"approved","label":"Approve"},{"from":"ap14","to":"a9","branch":"rejected","label":"Return For Changes"},{"from":"a15","to":"c16"},{"from":"c16","to":"a17","branch":"true","label":"Yes"},{"from":"c16","to":"a8","branch":"false","label":"No"},{"from":"a17","to":"e18"}],"metadata":{"name":"NCR Process","module":"ncr","category":"quality","ownerDepartment":"quality","description":"One NCR process: quality review, containment, root cause, corrective action, implementation, approval, and effectiveness. Side paths and SLA rules stay on this workflow.","allowLoops":true,"sla":{"priorityFromSeverity":{"Critical":"Critical","Major":"High","Minor":"Normal"},"implementationRiskFromPriority":{"Critical":"Critical","High":"High","Normal":"Medium"},"implementationDays":{"Low":30,"Medium":21,"High":14,"Critical":7},"reminders":{"daysBefore":[7,3,1],"onDue":true,"daysOverdue":[1,3,7,14],"everyDaysAfter":7},"overallDays":{"Minor":30,"Major":45,"Critical":60},"overallWarnPercent":0.75,"overallEscalatePercent":0.9,"stages":{"Quality Review":{"hours":24,"warnHoursRemaining":12,"overdueTargets":["Quality Manager","Operations Manager"],"escalateAfterDays":3,"escalateTargets":["Executive Management"]},"Containment":{"hoursBySeverity":{"Minor":null,"Major":24,"Critical":4},"overdueTargets":["Production Manager","Quality Manager"],"escalateAfterHours":24,"escalateTargets":["Operations Director"]},"Root Cause Analysis":{"businessDays":{"Minor":5,"Major":3,"Critical":2},"warnAtPercent":0.8,"warnTargets":["RCA owner"],"overdueTargets":["Quality Manager","Engineering Manager"],"escalateAfterDays":5,"escalateTargets":["Executive Management"]},"Corrective Action":{"businessDays":{"Minor":5,"Major":3,"Critical":2},"overdueTargets":["action owner","Quality Manager"],"escalateAfterDays":3,"escalateTargets":["Operations Manager"]},"Implementation":{"overdueTargets":["task owner","Quality Manager"],"escalateAfterDays":7,"escalateTargets":["Department Manager"],"executiveAfterDays":14,"executiveTargets":["Executive Management"]},"Management Approval":{"businessDays":3,"overdueTargets":["approvers"],"escalateAfterDays":5,"escalateTargets":["Executive Management"]},"Effectiveness Verification":{"daysAfterAction":30,"criticalDays":15,"approachingTargets":["Quality Manager"],"overdueTargets":["Quality Manager","Operations Manager"]}},"overallExceededTargets":["Quality Manager","Operations Manager","Executive Sponsor"],"side":{"openMoreThanDays":30,"openTargets":["Quality Manager","Operations Manager","Executive Sponsor"],"openEscalationLevel":"High","criticalTargets":["President","CEO","Operations Director"],"customerResponseHours":48,"customerTargets":["Sales Manager","Quality Manager"],"supplierAssignee":"Supplier Quality Engineer","supplierTargets":["Supplier Quality Engineer","Quality Manager"],"correctiveOverdueTargets":["action owner","Quality Manager"]}},"slaSummary":["Quality Review is due 1 day after the NCR is submitted. At 12 hours remaining, Quality Manager is notified. Overdue notifies Quality Manager and Operations Manager. More than 3 days overdue is Escalated to Executive Management.","Containment: Minor has no stage deadline. Major is due in 24 hours. Critical is due in 4 hours. Overdue notifies Production Manager and Quality Manager. More than 24 hours overdue escalates to Operations Director.","Root cause: Minor 5 business days, Major 3, Critical 2. At 80% of the SLA the RCA owner is notified. Overdue notifies Quality Manager and Engineering Manager. More than 5 days overdue escalates to executive review.","Corrective action planning uses the same business-day counts as root cause. Overdue notifies the action owner and Quality Manager. More than 3 days overdue escalates to Operations Manager.","Implementation: Low risk 30 days, Medium 21, High 14, Critical 7. A passed due date notifies the task owner and Quality Manager. More than 7 days overdue notifies the Department Manager. More than 14 days requires executive escalation.","Management approval is due in 3 business days. Overdue notifies the approvers. More than 5 days overdue escalates to executive management.","Effectiveness is due 30 days after the last corrective action is done, or 15 days for a Critical NCR. An approaching due date notifies Quality Manager. Overdue notifies Quality Manager and Operations Manager.","Overall close: Minor 30 days, Major 45, Critical 60, measured by days open. At 75% an early warning is sent. At 90% an escalation warning is sent. Past the target, status is Escalated and Quality Manager, Operations Manager, and Executive Sponsor are notified.","Priority follows severity: Critical, Major as High, Minor as Normal.","Reminders are in-app notices at 7, 3, and 1 day before the due date, on the due date, then 1, 3, 7, and 14 days overdue, then every 7 days until the NCR is closed."]}}$ncrdef$::jsonb, 1, '[]'::jsonb
WHERE NOT EXISTS (
  SELECT 1 FROM "workflow_definitions" WHERE "name" = 'NCR Process' AND "module" = 'ncr'
);--> statement-breakpoint
INSERT INTO "controlled_versions" ("subject_type", "subject_id", "version_number", "status", "payload", "metadata", "published_at")
SELECT 'workflow', d."id", 1, 'published', d."definition", '{"changeSummary":"NCR Process with stage SLAs"}'::jsonb, now()
FROM "workflow_definitions" d
WHERE d."name" = 'NCR Process' AND d."module" = 'ncr'
  AND NOT EXISTS (
    SELECT 1 FROM "controlled_versions" cv
    WHERE cv."subject_type" = 'workflow' AND cv."subject_id" = d."id" AND cv."version_number" = 1
  );
